-- Batch 2: Thai translations for Vanguard cards, covering 1000 DISTINCT
-- skill_text values (4262 real cards total) that were still untranslated
-- after batch 1. Unlike batch 1 (which matched one UPDATE per card_number),
-- this batch's export script (scripts/export-untranslated-batch.js) groups
-- by skill_text first, since 41% of batch 1's rows turned out to be exact
-- duplicate text under different card_number values -- so every UPDATE
-- below matches on skill_text directly, which naturally fixes every card
-- sharing that exact text in one statement, duplicates included.
--
-- Translated in 10 parallel chunks of 100 by sub-agents sharing one
-- glossary (scratchpad GLOSSARY.md), then merged and validated centrally:
--   - all 1000 skill_text values cross-checked byte-for-byte against the
--     original exported CSV (exact match, nothing missing/extra)
--   - zero Japanese/Korean/Chinese characters in any translation (regex
--     scan over the full merged set, including the easy-to-miss katakana
--     "・" bullet which looks like plain punctuation)
--   - the batch-1 "Over Trigger" mistake specifically re-checked
--     ("超トリガー" must be "โอเวอร์ทริกเกอร์", never "ซุปเปอร์ทริกเกอร์"):
--     0 occurrences of the wrong term, all 15 real instances correct
--   - cross-chunk terminology inconsistencies found during the merge were
--     reconciled to one canonical choice each:
--       * 呪縛/解呪 -> "ล็อค"/"ปลดล็อค" (confirmed official English term is
--         "Lock"/"Unlocked", separate from "Bind" which is baindo already
--         shipped elsewhere) -- some chunks had used "สาป" (curse), fixed
--       * 世界 (World) -> "เวิลด์" (loanword, matches batch 1's own usage)
--         -- some chunks had used plain "โลก", fixed
--       * 英勇 (unconfirmed official EN term) -> transliterated "เออิยู"
--         consistently (some chunks had "วีรบุรุษ"/"ผู้กล้าหาญ", fixed)
--       * 真宵楽園 (World name, official EN "Stray Garden") ->
--         transliterated "มาโยอิรากุเอ็ง" consistently (some chunks had
--         translated it by meaning as "สรวงสวรรค์...", fixed)
--     NOTE: smaller one-off spelling variance in transliterated unit/card
--     proper nouns (e.g. a name rendered slightly differently by two
--     different chunks) was intentionally left alone, per this project's
--     own glossary guidance not to block delivery chasing a "perfect"
--     spelling for names with no established Thai spelling -- flagging
--     this here in case a future human pass wants to tighten it further.
--   - test-run against a throwaway local Postgres table seeded with
--     duplicate skill_text rows before being sent, confirming a single
--     UPDATE really does fix every card sharing that text, not just one
--
-- Only updates cards still missing a translation (skill_text_th IS NULL),
-- so re-running this is always safe even if some of these cards already
-- got translated another way (e.g. the lazy per-card translator) in the
-- meantime.
--
-- Uses plain single-quoted strings (standard SQL '' escaping, no
-- dollar-quoting), matching batch 1's style.
--
-- Run from the server/ directory, in your own terminal:
--   psql "$(grep -E '^DATABASE_URL=' .env | cut -d'=' -f2-)" -f sql/batch2-manual-translations.sql

BEGIN;

UPDATE cards SET skill_text_th = '※ไม่สามารถใช้ในไฟท์ได้', updated_at = now() WHERE game = 'vanguard' AND skill_text = '※ファイトでは使用できません。' AND skill_text_th IS NULL;
UPDATE cards SET skill_text_th = 'เอฟเฟกต์เพิ่มเติม - เลือกยูนิตของคุณ 1 ใบ ตลอดเทิร์นนั้น พาวเวอร์ +1 ร้อยล้าน!', updated_at = now() WHERE game = 'vanguard' AND skill_text = '追加効果－あなたのユニットを１枚選び、そのターン中、パワー＋１億！' AND skill_text_th IS NULL;
UPDATE cards SET skill_text_th = '[AUTO]: เมื่อยูนิตนี้ถูกวางที่ (G) จากมือ ถ้าในไฟท์นี้คุณยังไม่ได้ไรด์เกรด 3 ขึ้นไป ให้ทำอย่างใดอย่างหนึ่งต่อไปนี้ 1 อย่าง
•เลือกแวนการ์ดของคุณ 1 ใบ ตลอดเทิร์นนั้น พาวเวอร์ +10000
•เลือกยูนิตของฝ่ายตรงข้าม 1 ใบ ตลอดบัตเทิลนั้น คริติคอล -2
[AUTO]: เมื่อยูนิตนี้ปรากฏตัวที่ (R) จากมือ ถ้าดาเมจโซนของคุณมี 0 ใบ ให้วางการ์ดบนสุดของเด็ค 1 ใบลงดาเมจโซน', updated_at = now() WHERE game = 'vanguard' AND skill_text = '【自】：このユニットが手札から(G)に置かれた時、このファイトであなたがグレード３以上にライドしていないなら、以下を１つ行う。
・あなたのヴァンガードを１枚選び、そのターン中、パワー＋10000。
・相手のユニットを１枚選び、そのバトル中、クリティカル－２。
【自】：このユニットが手札から(R)に登場した時、あなたのダメージゾーンが０枚なら、山札を上から１枚ダメージゾーンに置く。' AND skill_text_th IS NULL;
UPDATE cards SET skill_text_th = '(การ์ดฮีลทริกเกอร์ใส่ในเด็คได้รวมสูงสุด 4 ใบ)', updated_at = now() WHERE game = 'vanguard' AND skill_text = '（【治】はデッキに合計４枚まで入れられる）' AND skill_text_th IS NULL;
UPDATE cards SET skill_text_th = '(ถ้าออกมาเป็นทริกเกอร์ จั่ว 1 ใบ! จากนั้นเลือกยูนิตของคุณ 1 ใบ ตลอดเทิร์นนั้น พาวเวอร์ +10000!)', updated_at = now() WHERE game = 'vanguard' AND skill_text = '（トリガーで出たら、１枚引く！さらにあなたのユニットを１枚選び、そのターン中、パワー＋10000！）' AND skill_text_th IS NULL;
UPDATE cards SET skill_text_th = '(ถ้าออกมาเป็นทริกเกอร์ เลือกยูนิตของคุณ 1 ใบ ตลอดเทิร์นนั้น คริติคอล +1! จากนั้นเลือกยูนิตของคุณ 1 ใบ ตลอดเทิร์นนั้น พาวเวอร์ +10000!)', updated_at = now() WHERE game = 'vanguard' AND skill_text = '（トリガーで出たら、あなたのユニットを１枚選び、そのターン中、クリティカル＋１！さらにあなたのユニットを１枚選び、そのターン中、パワー＋10000！）' AND skill_text_th IS NULL;
UPDATE cards SET skill_text_th = '(ถ้าออกมาเป็นทริกเกอร์ ตลอดเทิร์นนั้น พาวเวอร์ของยูนิตแนวหน้าทั้งหมดของคุณ +10000!)', updated_at = now() WHERE game = 'vanguard' AND skill_text = '（トリガーで出たら、そのターン中、あなたの前列のユニットすべてのパワー＋10000！）' AND skill_text_th IS NULL;
UPDATE cards SET skill_text_th = '[AUTO][ไรด์เด็ค]: เมื่อคุณไรด์ ให้วางการ์ดนี้ลงเครสต์โซน และถ้าคุณเป็นฝ่ายเล่นที่สอง เอนเนอร์จีชาร์จ(3)
[CONT]: คุณถือเอนเนอร์จีได้สูงสุด 10 หน่วย
[AUTO]: เมื่อเริ่มไรด์เฟสของคุณ เอนเนอร์จีชาร์จ(3)
[ACT][เทิร์นละ 1 ครั้ง]: [COST][เอนเนอร์จีบลาสต์(7)] เพื่อจั่ว 1 ใบ', updated_at = now() WHERE game = 'vanguard' AND skill_text = '【自】【ライドデッキ】：あなたがライドした時、このカードをクレストゾーンに置き、あなたが後攻なら、【エネルギーチャージ】(3)。
【永】：あなたはエネルギーを10個まで持てる。
【自】：あなたのライドフェイズ開始時、【エネルギーチャージ】(3)。
【起】【ターン1回】：【コスト】[【エネルギーブラスト】(7)]することで、１枚引く。' AND skill_text_th IS NULL;
UPDATE cards SET skill_text_th = '[AUTO]: เมื่อยูนิตนี้ริไทร์จาก (G) คุณสามารถวางการ์ดนี้ลงโซลได้', updated_at = now() WHERE game = 'vanguard' AND skill_text = '【自】：このユニットが(G)から退却した時、このカードをソウルに置いてよい。' AND skill_text_th IS NULL;
UPDATE cards SET skill_text_th = '[AUTO][(R)][G เบรก](1): เมื่อแวนการ์ดของคุณแอทแทค [COST][วางยูนิตนี้ลงโซล] เพื่อจั่ว 1 ใบ และเลือกแวนการ์ดของคุณ 1 ใบ ตลอดบัตเทิลนั้น พาวเวอร์ +10000', updated_at = now() WHERE game = 'vanguard' AND skill_text = '【自】【(R)】【Gブレイク】(1)：あなたのヴァンガードがアタックした時、【コスト】[このユニットをソウルに置く]ことで、１枚引き、あなたのヴァンガードを１枚選び、そのバトル中、パワー＋10000。' AND skill_text_th IS NULL;
UPDATE cards SET skill_text_th = '[CONT][มือ]: ตอนที่คุณจ่ายต้นทุนของ[สไตรด์] คุณสามารถทิ้งการ์ดนี้โดยนับเป็นเกรด 3 ได้', updated_at = now() WHERE game = 'vanguard' AND skill_text = '【永】【手札】：あなたが【超越】のコストを払う際、このカードをグレード３として捨ててよい。' AND skill_text_th IS NULL;
UPDATE cards SET skill_text_th = '[AUTO]: เมื่อยูนิตนี้ถูกไรด์ จั่ว 1 ใบ นอกจากนี้ ถ้าแวนการ์ดของฝ่ายตรงข้ามเป็นเกรด 1 ขึ้นไป คุณเพิ่มควิกชีลด์ทิกเก็ต 1 ใบเข้ามือ', updated_at = now() WHERE game = 'vanguard' AND skill_text = '【自】：このユニットがライドされた時、１枚引く。さらに、相手のヴァンガードがグレード１以上なら、あなたはクイックシールド・チケットを１枚手札に加える。' AND skill_text_th IS NULL;
UPDATE cards SET skill_text_th = '[CONT]: การ์เดียน (การ์ดที่มีการ์เดียนใส่ในเด็คได้รวมสูงสุด 4 ใบ)
[AUTO]: เมื่อยูนิตนี้ถูกวางที่ (G) [COST][ทิ้งการ์ดจากมือ 1 ใบ] เพื่อเลือกยูนิตของคุณ 1 ใบ ตลอดบัตเทิลนั้น จะไม่ถูกฮิต', updated_at = now() WHERE game = 'vanguard' AND skill_text = '【永】：守護者（守護者を持つカードはデッキに合計４枚まで入れられる）
【自】：このユニットが(G)に置かれた時、【コスト】[手札から１枚捨てる]ことで、あなたのユニットを１枚選び、そのバトル中、ヒットされない。' AND skill_text_th IS NULL;
UPDATE cards SET skill_text_th = '[AUTO]: เมื่อการ์ดนี้ถูกทิ้งจากมือเป็นต้นทุนในการคอล [G การ์เดียน] [COST][ไบนด์การ์ดนี้ และไบนด์การ์ดฮีลทริกเกอร์ใบอื่นจากดรอป 1 ใบ] เพื่อเคาน์เตอร์ชาร์จ(1) หรือโซลชาร์จ(1)', updated_at = now() WHERE game = 'vanguard' AND skill_text = '【自】：このカードが【Ｇガーディアン】をコールするコストで手札から捨てられた時、【コスト】[このカードをバインドし、ドロップから他の【治】を１枚バインドする]ことで、【カウンターチャージ】(1)か【ソウルチャージ】(1)。' AND skill_text_th IS NULL;
UPDATE cards SET skill_text_th = '[CONT]: การ์เดียน
[AUTO]: เมื่อยูนิตนี้ปรากฏตัวที่ (G) [COST][ทิ้งการ์ดจากมือ 1 ใบ] เพื่อให้ยูนิตของคุณ 1 ใบ ตลอดบัตเทิลนั้น จะไม่ถูกฮิต', updated_at = now() WHERE game = 'vanguard' AND skill_text = '【永】：守護者
【自】：このユニットが(G)に登場した時、【コスト】[手札から１枚捨てる]ことで、そのバトル中、あなたのユニット１枚はヒットされない。' AND skill_text_th IS NULL;
UPDATE cards SET skill_text_th = '[CONT]: การ์เดียน (การ์ดที่มีการ์เดียนใส่ในเด็คได้รวมสูงสุด 4 ใบ)', updated_at = now() WHERE game = 'vanguard' AND skill_text = '【永】：守護者（守護者を持つカードは合計でデッキに４枚まで入れられる）' AND skill_text_th IS NULL;
UPDATE cards SET skill_text_th = 'เลือกยูนิตที่กำลังถูกแอทแทค 1 ใบ ตลอดบัตเทิลนั้น พาวเวอร์ +10000 และตลอดเทิร์นนั้น คุณสามารถเล่นบลิตซ์ออร์เดอร์ได้สูงสุด 2 ครั้ง จากนั้น ถ้าในเครสต์โซนของฝ่ายตรงข้ามมีการ์ดอื่นที่ไม่ใช่ "เอนเนอร์จี เจเนอเรเตอร์" พาวเวอร์ +5000 เพิ่มเติม

[CONT][มือ]: ในเทิร์นของคุณ คุณไม่สามารถเลือกการ์ดนี้ตอนทิ้งการ์ดเพื่อไรด์จากไรด์เด็ค หรือตอนเลือกการ์ดในมือด้วยความสามารถของการ์ดคุณเอง และไม่สามารถทิ้งการ์ดนี้ได้', updated_at = now() WHERE game = 'vanguard' AND skill_text = 'アタックされているユニットを１枚選び、そのバトル中、パワー+10000し、そのターン中、あなたはブリッツオーダーを２回までプレイできる。その後、相手のクレストゾーンに「エネルギージェネレーター」以外のカードがあるなら、さらにパワー+5000。

【永】【手札】：あなたのターン中、あなたは、ライドデッキからライドする際に捨てる際や、自分のカードの能力で手札を選ぶ際、このカードを選べず、捨てられない。' AND skill_text_th IS NULL;
UPDATE cards SET skill_text_th = '(การ์ดฮีลทริกเกอร์ใส่ในเด็คได้รวมสูงสุด 4 ใบ ถ้าออกมาเป็นทริกเกอร์ เลือกยูนิตของคุณ 1 ใบ ตลอดเทิร์นนั้น พาวเวอร์ +10000! จากนั้นถ้าจำนวนดาเมจโซนของคุณมากกว่าหรือเท่ากับฝ่ายตรงข้าม เลือกการ์ด 1 ใบจากดาเมจโซนของคุณ แล้วฮีล!)', updated_at = now() WHERE game = 'vanguard' AND skill_text = '（【治】はデッキに合計４枚まで入れられる。トリガーで出たら、あなたのユニットを１枚選び、そのターン中、パワー＋10000！さらにあなたのダメージゾーンの枚数が相手以上なら、あなたのダメージゾーンから１枚選び、回復する！）' AND skill_text_th IS NULL;
UPDATE cards SET skill_text_th = '[CONT]: ระหว่างการ์ดสเตปในเทิร์นของฝ่ายตรงข้าม การ์ดนี้สามารถคอลลงที่ (G) ในฐานะทริกเกอร์ยูนิตได้ และกลายเป็นการ์เดียนเกรด 0 / ชีลด์ 15000', updated_at = now() WHERE game = 'vanguard' AND skill_text = '【永】：相手ターンのガードステップ中、このカードはトリガーユニットとして(G)にコールでき、グレード０/シールド15000のガーディアンになる。' AND skill_text_th IS NULL;
UPDATE cards SET skill_text_th = '[AUTO]: เมื่อยูนิตนี้ปรากฏตัวที่ (R) จากมือ ถ้าเทิร์นนี้คุณยังไม่ได้เล่นออร์เดอร์ [COST][ทิ้งการ์ดจากมือ 1 ใบ] เพื่อค้นหาการ์ดออร์เดอร์ที่ไม่มี [เลกาลิส พีซ] จากเด็คของคุณสูงสุด 1 ใบ ทิ้งมัน และตลอดเทิร์นนั้น มอบความสามารถ『[CONT]: การ์ดนี้สามารถเล่นได้จากดรอปด้วย และเมื่อถูกเล่นแล้วจะถูกวางลงดรอป ให้วางลงใต้เด็คแทน』ให้กับการ์ดนั้น จากนั้นสับเด็ค', updated_at = now() WHERE game = 'vanguard' AND skill_text = '【自】：このユニットが手札から(R)に登場した時、このターンにあなたがオーダーをプレイしていないなら、【コスト】[手札から１枚捨てる]ことで、あなたの山札から、【レガリスピース】を持たないオーダーカードを１枚まで探し、捨て、そのターン中、『【永】：このカードはドロップからでもプレイでき、プレイされてドロップに置く際、かわりに山札の下に置く。』を与える。山札をシャッフルする。' AND skill_text_th IS NULL;
UPDATE cards SET skill_text_th = '[CONT][(R) แนวหน้า]: ในเทิร์นของคุณ ความสามารถ [AUTO] จะไม่ทำงานตอนฝ่ายตรงข้ามอินเตอร์เซ็ปต์ และยูนิตของฝ่ายตรงข้ามทุกใบที่ถูกวางจาก (R) ไปยัง (G) จะสูญเสียความสามารถ [CONT] และ [AUTO] ทั้งหมด', updated_at = now() WHERE game = 'vanguard' AND skill_text = '【永】【前列の(R)】：あなたのターン中、相手のインターセプトでは【自】能力は発動せず、(R)から(G)に置かれた相手のユニットすべては、【永】能力と【自】能力すべてを失う。' AND skill_text_th IS NULL;
UPDATE cards SET skill_text_th = '[AUTO]: เมื่อการ์ดนี้ปรากฏตัวที่ (R) จากมือโดยไม่ใช่ความสามารถของการ์ดยูนิต หรือถูกทิ้งตอนไรด์จากไรด์เด็ค คุณสามารถเลือกการ์ดที่มีเพอร์โซนาไรด์จากไรด์เด็คของคุณ 1 ใบ แล้วเปิดเผยได้ ถ้าเปิดเผยแล้ว หรือแวนการ์ดของคุณมีเพอร์โซนาไรด์ [COST][โซลบลาสต์(1)] เพื่อเพิ่มเพอร์โซนาชีลด์ทิกเก็ต 1 ใบเข้ามือ
