UPDATE cards SET skill_text_th = 'เปิดเด็คของคุณจากบนสุด 5 ใบ เลือกการ์ดยูนิตที่มีคำว่า "ริวจู" หรือ "มาสคุส" สูงสุด 1 ใบ เปิดเผยแล้วเพิ่มเข้ามือ จากนั้นสับเด็ค

