UPDATE cards SET skill_text_th = '[AUTO]: เมื่อยูนิตนี้ลงสนามที่ (R) จ่าย [COST][เคาน์เตอร์บลาสต์ (1)] หรือ [วางยูนิตทริกเกอร์จากมือลงโซล 1 ใบ] เพื่อดูเด็คของคุณ 7 ใบจากบนสุด เลือกการ์ดที่มีชื่อรวม "คุราตะ มาชิโระ" สูงสุด 1 ใบ แล้วเปิดเผยและเพิ่มลงมือ จากนั้นสับเด็ค ถ้าไม่ได้เปิดเผย ให้ [เคาน์เตอร์ชาร์จ] (1)
