UPDATE cards SET skill_text_th = '[AUTO][(R) แถวหลัง]: เมื่อเริ่มเฟสบัตเทิลของคุณ ถ้าแวนการ์ดของคุณมีคำว่า "แกรนเฟีย" คอลโทเคนแพลนต์ได้สูงสุด 1 ใบลงที่ (R) และถ้าใน (R) ของคุณมีโทเคนโนเบลสโรสอยู่ ให้จ่าย [COST][เคาน์เตอร์บลาสต์ (1)] เพิ่มเติม เพื่อจั่ว 1 ใบ', updated_at = now() WHERE game = 'vanguard' AND skill_text = '【自】【後列の(R)】：あなたのバトルフェイズ開始時、「グランフィア」を含むあなたのヴァンガードがいるなら、プラント・トークンを１枚まで(R)にコールし、あなたの(R)にノブレスローズ・トークンがいるなら、さらに【コスト】[【カウンターブラスト】(1)]することで、１枚引く。' AND skill_text_th IS NULL;
