UPDATE cards SET skill_text_th = '[AUTO]: เมื่อการ์ดนี้ถูกนำไปโซลด้วยความสามารถของการ์ดของคุณ ถ้าแวนการ์ดของคุณเป็นแคลน《เพลมูน》เท่านั้น จ่าย [COST][ไบนด์การ์ดนี้] เพื่อค้นหาเกรด 3 จากเด็คหรือดรอปของคุณ 1 ใบ แล้วนำไปโซล ถ้าค้นจากเด็ค ให้สับเด็ค', updated_at = now() WHERE game = 'vanguard' AND skill_text = '【自】：このカードがあなたのカードの能力でソウルに置かれた時、クランが《ペイルムーン》のみのあなたのヴァンガードがいるなら、【コスト】[このカードをバインドする]ことで、あなたの、山札かドロップから、グレード３を１枚まで探し、ソウルに置く。山札から探したら、山札をシャッフルする。' AND skill_text_th IS NULL;
